package lombok.javac.handlers;

import static com.sun.tools.javac.code.Flags.*;
import static lombok.core.handlers.HandlerUtil.*;
import static lombok.javac.handlers.JavacHandlerUtil.*;
import static lombok.javac.handlers.JavacResolver.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import javax.lang.model.element.ElementKind;

import lombok.ConfigurationKeys;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.HandlerPriority;
import lombok.core.JavaIdentifiers;
import lombok.experimental.ExtensionMethod;
import lombok.javac.Javac;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacAugments;
import lombok.javac.JavacNode;
import lombok.javac.JavacResolution;
import lombok.javac.JavacTreeMaker;
import lombok.spi.Provides;

import com.sun.source.tree.MethodInvocationTree;
import com.sun.source.util.TreeScanner;
import com.sun.tools.javac.code.Symbol;
import com.sun.tools.javac.code.Symbol.ClassSymbol;
import com.sun.tools.javac.code.Symbol.MethodSymbol;
import com.sun.tools.javac.code.Symbol.TypeSymbol;
import com.sun.tools.javac.code.Symbol.VarSymbol;
import com.sun.tools.javac.code.Type;
import com.sun.tools.javac.code.Type.ClassType;
import com.sun.tools.javac.code.Type.ErrorType;
import com.sun.tools.javac.code.Type.ForAll;
import com.sun.tools.javac.code.Type.MethodType;
import com.sun.tools.javac.code.Types;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCCompilationUnit;
import com.sun.tools.javac.tree.JCTree.JCExpression;
import com.sun.tools.javac.tree.JCTree.JCFieldAccess;
import com.sun.tools.javac.tree.JCTree.JCIdent;
import com.sun.tools.javac.tree.JCTree.JCImport;
import com.sun.tools.javac.tree.JCTree.JCMethodDecl;
import com.sun.tools.javac.tree.JCTree.JCMethodInvocation;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;
import com.sun.tools.javac.util.ListBuffer;
import com.sun.tools.javac.util.Name;

/**
 * Handles the {@link ExtensionMethod} annotation for javac.
 */
@Provides
@HandlerPriority(66560) // 2^16 + 2^10; we must run AFTER HandleVal which is at 2^16
public class HandleExtensionMethod extends JavacAnnotationHandler<ExtensionMethod> {
	@Override
	public void handle(final AnnotationValues<ExtensionMethod> annotation, final JCAnnotation source, final JavacNode annotationNode) {
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.EXTENSION_METHOD_FLAG_USAGE, "@ExtensionMethod");

		if (!inNetbeansEditor(annotationNode) && annotationNode.shouldDeleteLombokAnnotations()) {
			JavacNode parentNode = annotationNode.directUp();
			Kind parentKind = parentNode.getKind();
			JCTree annotationTree = annotationNode.get();
			if (parentKind == Kind.FIELD || parentKind == Kind.ARGUMENT || parentKind == Kind.LOCAL) {
				JCVariableDecl variable = (JCVariableDecl) parentNode.get();
				ListBuffer<JCAnnotation> variableAnnotations = new ListBuffer<JCAnnotation>();
				for (JCAnnotation existingAnnotation : variable.mods.annotations) {
					if (existingAnnotation != annotationTree) {
						variableAnnotations.append(existingAnnotation);
					}
				}
				variable.mods.annotations = variableAnnotations.toList();
			} else if (parentKind == Kind.METHOD) {
				JCMethodDecl method = (JCMethodDecl) parentNode.get();
				ListBuffer<JCAnnotation> methodAnnotations = new ListBuffer<JCAnnotation>();
				for (JCAnnotation existingAnnotation : method.mods.annotations) {
					if (existingAnnotation != annotationTree) {
						methodAnnotations.append(existingAnnotation);
					}
				}
				method.mods.annotations = methodAnnotations.toList();
			} else if (parentKind == Kind.TYPE) {
				try {
					JCClassDecl type = (JCClassDecl) parentNode.get();
					ListBuffer<JCAnnotation> typeAnnotations = new ListBuffer<JCAnnotation>();
					for (JCAnnotation existingAnnotation : type.mods.annotations) {
						if (existingAnnotation != annotationTree) {
							typeAnnotations.append(existingAnnotation);
						}
					}
					type.mods.annotations = typeAnnotations.toList();
				} catch (ClassCastException ignore) {
				}
			}
			parentNode.getAst().setChanged();
			JCCompilationUnit unit = (JCCompilationUnit) annotationNode.top().get();
			String annotationTypeName = ExtensionMethod.class.getName();
			for (JCTree def : unit.defs) {
				if (def instanceof JCImport) {
					JCImport imported = (JCImport) def;
					String importedName = imported.qualid.toString();
					if (!imported.staticImport && annotationTypeName.equals(importedName)) {
						JavacAugments.JCImport_deletable.set(imported, true);
					}
				}
			}
		}

		JavacNode typeNode = annotationNode.up();
		JCClassDecl annotatedType = null;
		long annotatedFlags = 0;
		if (typeNode.get() instanceof JCClassDecl) {
			annotatedType = (JCClassDecl) typeNode.get();
			annotatedFlags = annotatedType.mods.flags;
		}
		boolean annotatedIsInterface = (annotatedFlags & INTERFACE) != 0;
		boolean annotatedIsEnum = (annotatedFlags & ENUM) != 0;
		boolean annotatedIsAnnotation = (annotatedFlags & ANNOTATION) != 0;
		boolean annotatedIsRecord = (annotatedFlags & Javac.RECORD) != 0;
		boolean annotatedIsClass = (annotatedFlags & (INTERFACE | ENUM | ANNOTATION | Javac.RECORD)) == 0;
		boolean isClassOrEnumOrInterface = annotatedType != null && !annotatedIsAnnotation && !annotatedIsRecord;
		if (!isClassOrEnumOrInterface) {
			annotationNode.addError("@ExtensionMethod can only be used on a class or an enum or an interface");
			return;
		}

		boolean suppressBaseMethods = annotation.getInstance().suppressBaseMethods();
		List<Object> extensionProviders = annotation.getActualExpressions("value");
		if (extensionProviders.isEmpty()) {
			annotationNode.addError(String.format("@%s has no effect since no extension types were specified.", ExtensionMethod.class.getName()));
			return;
		}

		final List<Extension> extensions = new ArrayList<Extension>();
		for (Object extensionProvider : extensionProviders) {
			if (extensionProvider instanceof JCFieldAccess) {
				JCFieldAccess provider = (JCFieldAccess) extensionProvider;
				Name providerName = provider.name;
				JCExpression selected = provider.selected;
				if (providerName != null && selected != null && "class".equals(providerName.toString())) {
					Type providerType = selected.type;
					if (providerType == null) {
						try {
							new JavacResolution(annotationNode.getContext()).resolveClassMember(annotationNode);
							providerType = selected.type;
						} catch (Exception ignore) {
							providerType = selected.type;
						}
					}
					if (providerType != null) {
						TypeSymbol providerSymbol = providerType.tsym;
						if (providerSymbol != null) {
							long providerFlags = providerSymbol.flags();
							boolean providerIsInterface = (providerFlags & INTERFACE) != 0;
							boolean providerIsAnnotation = (providerFlags & ANNOTATION) != 0;
							if (!providerIsInterface && !providerIsAnnotation) {
								extensions.add(getExtension(annotationNode, (ClassType) providerType));
							}
						}
					}
				}
			}
		}
		if (extensions.isEmpty()) return;

		final List<JCMethodInvocation> invocations = new ArrayList<JCMethodInvocation>();
		typeNode.get().accept(new TreeScanner<Void, Void>() {
			@Override
			public Void visitMethodInvocation(final MethodInvocationTree tree, final Void p) {
				super.visitMethodInvocation(tree, p);
				invocations.add((JCMethodInvocation) tree);
				return null;
			}
		}, null);

		Types types = Types.instance(annotationNode.getContext());
		JavacTreeMaker maker = annotationNode.getTreeMaker();
		for (JCMethodInvocation methodCall : invocations) {
			JavacNode methodCallNode = annotationNode.getAst().get(methodCall);
			if (methodCallNode == null) continue;
			JavacNode surroundingType = methodCallNode;
			while (surroundingType != null && !(surroundingType.get() instanceof JCClassDecl)) {
				surroundingType = surroundingType.up();
			}
			JCClassDecl surroundingDecl = (JCClassDecl) surroundingType.get();
			TypeSymbol surroundingTypeSymbol = surroundingDecl.sym;
			long surroundingFlags = surroundingDecl.mods.flags;
			boolean surroundingIsInterface = (surroundingFlags & INTERFACE) != 0;
			boolean surroundingIsEnum = (surroundingFlags & ENUM) != 0;
			boolean surroundingIsAnnotation = (surroundingFlags & ANNOTATION) != 0;
			boolean surroundingIsRecord = (surroundingFlags & Javac.RECORD) != 0;
			JavacNode surroundingParent = surroundingType.directUp();
			boolean surroundingIsTopLevel = surroundingParent == null || surroundingParent.getKind() == Kind.COMPILATION_UNIT;
			boolean surroundingIsStatic = surroundingIsInterface || surroundingIsEnum || surroundingIsTopLevel || ((surroundingFlags & STATIC) != 0);
			JCExpression receiver;
			String methodName;
			if (methodCall.meth instanceof JCIdent) {
				receiver = maker.Ident(annotationNode.toName("this"));
				methodName = ((JCIdent) methodCall.meth).name.toString();
			} else {
				receiver = ((JCFieldAccess) methodCall.meth).selected;
				methodName = ((JCFieldAccess) methodCall.meth).name.toString();
			}
			if ("this".equals(receiver.toString()) || "this".equals(methodName) || "super".equals(methodName)) continue;
			boolean validMethodName = methodName != null && !methodName.isEmpty();
			if (validMethodName) {
				char firstChar = methodName.charAt(0);
				validMethodName = Character.isJavaIdentifierStart(firstChar);
				int nameLength = methodName.length();
				int nameIndex = 1;
				while (validMethodName && nameIndex < nameLength) {
					char currentChar = methodName.charAt(nameIndex);
					validMethodName = Character.isJavaIdentifierPart(currentChar);
					nameIndex++;
				}
			}
			boolean keywordName = JavaIdentifiers.isKeyword(methodName);
			if (validMethodName) validMethodName = !keywordName;
			boolean compilerGeneratedName = methodName.indexOf('$') >= 0;
			if (!validMethodName && !compilerGeneratedName) continue;
			Map<JCTree, JCTree> resolution = new JavacResolution(methodCallNode.getContext()).resolveMethodMember(methodCallNode);
			JCTree resolvedMethodCall = resolution.get(methodCall);
			if (resolvedMethodCall == null || resolvedMethodCall.type == null) continue;
			if (!suppressBaseMethods && !(resolvedMethodCall.type instanceof ErrorType)) continue;
			JCTree resolvedReceiver = resolution.get(receiver);
			if (resolvedReceiver == null || resolvedReceiver.type == null) continue;
			Type receiverType = resolvedReceiver.type;
			Symbol receiverSymbol = null;
			if (resolvedReceiver instanceof JCIdent) {
				receiverSymbol = ((JCIdent) resolvedReceiver).sym;
			} else if (resolvedReceiver instanceof JCFieldAccess) {
				receiverSymbol = ((JCFieldAccess) resolvedReceiver).sym;
			}
			if (receiverSymbol instanceof ClassSymbol) continue;
			boolean rewritten = false;
			for (Extension extension : extensions) {
				TypeSymbol extensionProvider = extension.extensionProvider;
				if (surroundingTypeSymbol != extensionProvider) {
					String providerFqn = extensionProvider.toString();
					for (MethodSymbol extensionMethod : extension.extensionMethods) {
						String extensionMethodName = extensionMethod.name.toString();
						if (methodName.equals(extensionMethodName)) {
							long extensionFlags = extensionMethod.flags();
							boolean extensionIsStatic = (extensionFlags & STATIC) != 0;
							boolean extensionIsPublic = (extensionFlags & PUBLIC) != 0;
							boolean extensionVisible = extensionIsStatic || extensionIsPublic;
							Type extensionMethodType = extensionMethod.type;
							boolean methodTypeUsable = MethodType.class.isInstance(extensionMethodType) || ForAll.class.isInstance(extensionMethodType);
							if (extensionVisible && methodTypeUsable) {
								com.sun.tools.javac.util.List<VarSymbol> extensionParams = extensionMethod.params();
								VarSymbol firstParam = extensionParams.get(0);
								MethodType asMethodType = extensionMethodType.asMethodType();
								com.sun.tools.javac.util.List<Type> argumentTypes = asMethodType.argtypes;
								Type rawFirstArgType = argumentTypes.get(0);
								Type firstParamType = firstParam.type;
								TypeSymbol firstParamSymbol = rawFirstArgType.tsym;
								String firstParamTypeText = rawFirstArgType.toString();
								boolean firstParamIsPrimitive = JavaIdentifiers.isPrimitive(firstParamTypeText);
								Type firstArgType = types.erasure(rawFirstArgType);
								boolean receiverCompatible = types.isAssignable(receiverType, firstArgType);
								Type returnType = asMethodType.restype;
								String returnTypeText = String.valueOf(returnType);
								int argumentCount = argumentTypes.size();
								int callArgumentCount = methodCall.args.size();
								int expectedCallArguments = argumentCount - 1;
								Type erasedReceiverType = types.erasure(receiverType);
								boolean primitiveReceiver = receiverType.isPrimitive();
								Name generatedMethodName = annotationNode.toName(methodName);
								String providerSimpleName = providerFqn;
								int providerNameLength = providerFqn.length();
								int methodNameLength = methodName.length();
								int replacementPathLength = providerNameLength + methodNameLength + 1;
								char pathSeparator = '.';
								String erasedReceiverText = String.valueOf(erasedReceiverType);
								String returnTypeText2 = returnTypeText;
								int remainingArgumentSlots = expectedCallArguments;
								boolean primitivePair = primitiveReceiver && firstParamIsPrimitive;
								int generatedNameLength = generatedMethodName.length();
								int simpleNameLength = providerSimpleName.length();
								String hostTypeName = surroundingDecl.name.toString();
								int hostTypeNameLength = hostTypeName.length();
								StringBuilder replacementPathBuilder = new StringBuilder(replacementPathLength);
								replacementPathBuilder.append(providerFqn);
								replacementPathBuilder.append(pathSeparator);
								replacementPathBuilder.append(methodName);
								String replacementPath = replacementPathBuilder.toString();
								if (receiverCompatible) {
									methodCall.args = methodCall.args.prepend(receiver);
									JCExpression generatedCall = chainDotsString(annotationNode, replacementPath);
									methodCall.meth = generatedCall;
									recursiveSetGeneratedBy(methodCall.meth, methodCallNode);
									rewritten = true;
								}
							}
						}
						if (rewritten) break;
					}
				}
				if (rewritten) break;
			}
		}

		annotationNode.rebuild();
	}


	public List<Extension> getExtensions(final JavacNode typeNode, final List<Object> extensionProviders) {
		List<Extension> extensions = new ArrayList<Extension>();
		for (Object extensionProvider : extensionProviders) {
			if (!(extensionProvider instanceof JCFieldAccess)) continue;
			JCFieldAccess provider = (JCFieldAccess) extensionProvider;
			if (!("class".equals(provider.name.toString()))) continue;
			Type providerType = CLASS.resolveMember(typeNode, provider.selected);
			if (providerType == null) continue;
			if ((providerType.tsym.flags() & (INTERFACE | ANNOTATION)) != 0) continue;

			extensions.add(getExtension(typeNode, (ClassType) providerType));
		}
		return extensions;
	}

	public Extension getExtension(final JavacNode typeNode, final ClassType extensionMethodProviderType) {
		List<MethodSymbol> extensionMethods = new ArrayList<MethodSymbol>();
		TypeSymbol tsym = extensionMethodProviderType.asElement();
		if (tsym != null) for (Symbol member : tsym.getEnclosedElements()) {
			if (member.getKind() != ElementKind.METHOD) continue;
			MethodSymbol method = (MethodSymbol) member;
			if ((method.flags() & (STATIC | PUBLIC)) == 0) continue;
			if (method.params().isEmpty()) continue;
			extensionMethods.add(method);
		}
		return new Extension(extensionMethods, tsym);
	}

	private static class Extension {
		final List<MethodSymbol> extensionMethods;
		final TypeSymbol extensionProvider;

		public Extension(List<MethodSymbol> extensionMethods, TypeSymbol extensionProvider) {
			this.extensionMethods = extensionMethods;
			this.extensionProvider = extensionProvider;
		}
	}
}

